    enc=[B64{:}];
    gzBytes=matlab.net.base64decode(enc);

    stageDir=fullfile(outdir,'STAGE');
    [ok,msg]=mkdir(stageDir); assert(ok,'%s',msg);
    gzPath=fullfile(stageDir,'REPLANNING_SYSTEM.m.gz');
    fz=fopen(gzPath,'wb'); assert(fz>=0);
    fwrite(fz,uint8(gzBytes),'uint8'); fclose(fz);
    gunzip(gzPath,stageDir);
    staged=fullfile(stageDir,'REPLANNING_SYSTEM.m');
    assert(isfile(staged),'[AF7R58ZZQ] staged source reconstruction failed.');

    stageSHA=file_hash(staged);
    OUT.staged_post_sha=stageSHA;
    assert(strcmp(stageSHA,POST_SHA), ...
        '[AF7R58ZZQ] embedded candidate SHA mismatch.');

    S=read_utf8_binary(staged);

    % ------------------------------------------------------------------
    % Static contract audit BEFORE production write.
    % ------------------------------------------------------------------
    assert(count_exact(S,'horizon_s     = 4.0;')==1, ...
        '[AF7R58ZZQ] fixed H=4 s default is not unique.');
    assert(~contains(S,'AF7R58ZZP theorem-derived EARLY intervention scheduler'), ...
        '[AF7R58ZZQ] forbidden extended-preview ZZP code is present.');
    assert(~contains(S,'prepare_early_intervention_reference_cache'), ...
        '[AF7R58ZZQ] forbidden extended-preview cache is present.');

    % Ordinary trigger remains H=obj.horizon_s.
    assert(contains(S, ...
        'g26_future_trigger_kernel_mex( ...'));
    assert(contains(S, ...
        'obj.horizon_s,obj.prediction_dt,obj.L_cable'));

    % New normal attempt budget.
    assert(count_exact(S,'attempt_budget_s=double(obj.prediction_dt);')==2, ...
        '[AF7R58ZZQ] expected generator+commit one-cycle budget bindings.');
    assert(contains(S, ...
        'FIXED_4S_HORIZON__ONE_CONTROL_PERIOD_SYNC_ATTEMPT_THEOREM'));
    assert(contains(S, ...
        'historical_4ms_used_as_normal_planner_deadline=false'));

    % Historical 4 ms still exists for stop/fallback geometry only.
    assert(count_exact(S,'hard_modify_deadline_s      = 4.0e-3;')==1);
    assert(contains(S, ...
        'clearanceAfterDeadline= ...'));
    assert(contains(S, ...
        'dDetLB-rho-VQ*double(obj.hard_modify_deadline_s)'));

    % Normal generator/commit functions must contain no live 4-ms deadline gate.
    G=function_slice(S, ...
        '        function invoke_replan_generator_shadow(obj,t_hard_cycle,t_now, ...', ...
        '        function ');
    C=function_slice(S, ...
        '        function [ok,reason] = try_commit_reference_only_proposal(obj,P,t_commit,t_hard_cycle)', ...
        '        function ');
    assert(~contains(G,'obj.hard_modify_deadline_s'), ...
        '[AF7R58ZZQ] legacy 4-ms gate remains in normal generator path.');
    % One textual mention is allowed in a comment inside commit.
    assert(count_exact(C,'obj.hard_modify_deadline_s')==0, ...
        '[AF7R58ZZQ] legacy 4-ms gate remains in normal commit executable path.');
    assert(contains(G,'cycle_ms>1e3*attempt_budget_s'));
    assert(contains(C,'toc(t_hard_cycle)>attempt_budget_s'));

    % Cache-preserving atomic ordering.
    pOld=strfind(C,'old=struct(');
    pConsume=strfind(C,'%% Consume only after the authoritative commit has closed.');
    pFinal=strfind(C,'elapsed=toc(t_hard_cycle);');
    assert(numel(pOld)==1&&numel(pConsume)==1&&~isempty(pFinal), ...
        '[AF7R58ZZQ] atomic ordering anchors unresolved.');
    pFinal=pFinal(end);
    assert(pOld<pFinal && pFinal<pConsume, ...
        '[AF7R58ZZQ] prepared-cache consume is not post-closure.');
    assert(contains(C,'explicit fail-closed'));
    assert(~contains(C, ...
        'error([''[REPLANNER DEADLINE] reference-only atomic commit '), ...
        '[AF7R58ZZQ] expected deadline miss still throws an exception.');

    % Finite sensing remains exact.
    assert(contains(S,'The generator receives ONLY sensor-known obstacles:'));
    assert(contains(S,'''detected_only_obstacle_contract'',true'));
    assert(contains(S,'Initial known set is empty.'));
    assert(contains(S,'raw_sensor_gate alone may admit a previously unknown obstacle.'));

    % Generator / certificate mathematics are not replaced.
    assert(contains(S,'RAW=af7r36_single_core_mex(1,pkt);'));
    assert(contains(S,'obj.evaluate_reference_only_proposal_certificate(candidate)'));
    assert(contains(S,'af7r58i_prepare_batch_model'));

    % Full class parse before first production write.
    parseDir=fullfile(outdir,'PARSE');
    [ok,msg]=mkdir(parseDir); assert(ok,'%s',msg);
    parseName='AF7R58ZZQ_PARSE_REPLANNING_SYSTEM';
    parseText=strrep(S,'classdef REPLANNING_SYSTEM < handle', ...
        ['classdef ' parseName ' < handle']);
    assert(~strcmp(parseText,S),'[AF7R58ZZQ] class rename failed.');
    parsePath=fullfile(parseDir,[parseName '.m']);
    write_utf8_binary(parsePath,parseText);
    addpath(parseDir,'-begin');
    cp=onCleanup(@()safe_rmpath(parseDir)); %#ok<NASGU>
    eval(['clear ' parseName]);
    mc=meta.class.fromName(parseName);
    assert(~isempty(mc),'[AF7R58ZZQ] candidate full-class parse failed.');
    eval(['clear ' parseName]);

    say(fid,'');
    say(fid,'[B. PREFLIGHT BEFORE PRODUCTION WRITE]');
    say(fid,' fixed collision horizon H=4 s            = 1');
    say(fid,' extended preview installed                = 0');
    say(fid,' ordinary trigger unchanged                = 1');
    say(fid,' normal planner budget = prediction_dt     = 1');
    say(fid,' historical 4ms normal planner gate        = 0');
    say(fid,' historical 4ms stop/fallback cert retained= 1');
    say(fid,' cache preserved until commit closure      = 1');
    say(fid,' expected budget miss uses ordinary rollback=1');
    say(fid,' finite sensing contract retained          = 1');
    say(fid,' native generator call retained            = 1');
    say(fid,' reference certificate call retained       = 1');
    say(fid,' full candidate class parse                = 1');
    say(fid,' production writes                         = 0');

    % Transactional exact-byte install.
    copyfile(pR,backup,'f');
    OUT.backup_path=backup;

    writeStarted=true;
    copyfile(staged,pR,'f');
    OUT.production_modified=true;
    post=file_hash(pR);
    OUT.post_sha=post;
    assert(strcmp(post,POST_SHA), ...
        '[AF7R58ZZQ] post-write bytes differ from reviewed candidate.');

    say(fid,'');
    say(fid,'[C. INSTALL RESULT]');
    say(fid,' post SHA                              = %s',post);
    say(fid,' staged/post exact byte identity        = 1');
    say(fid,' H=4 s changed                          = 0');
    say(fid,' generator/MEX math changed             = 0');
    say(fid,' continuous certificate math changed    = 0');
    say(fid,' finite sensing changed                 = 0');
    say(fid,' resource helper changed                = 0');

    OUT.status='FIXED4S_ONECYCLE_SUCCESS_ARCHITECTURE_INSTALLED__CLEAN_RERUN_REQUIRED';

catch ME
    OUT.error=struct('identifier',ME.identifier,'message',ME.message,'stack',{ME.stack});
    if writeStarted && isfile(backup)
        try
            copyfile(backup,pR,'f');
            OUT.rollback_performed=true;
            OUT.production_modified=false;
        catch
        end
    end
    OUT.status='INSTALL_FAILED__ROLLBACK_ATTEMPTED';

    say(fid,'');
    say(fid,'[INSTALL FAILURE]');
    say(fid,' identifier = %s',ME.identifier);
    say(fid,' message    = %s',ME.message);
    say(fid,' rollback   = %d',OUT.rollback_performed);
end

OUT.report_path=report;
OUT.mat_path=matp;
save(matp,'OUT','-v7');
say(fid,'');
say(fid,'RETURN: %s',report);
say(fid,'RETURN: %s',matp);
say(fid,'status = %s',OUT.status);
assignin('base','AF7R58ZZQ_OUT',OUT);
end

function F=function_slice(S,startToken,nextFunctionToken)
p=strfind(S,startToken);
assert(numel(p)==1,'[AF7R58ZZQ] function start token count=%d.',numel(p));
q=strfind(S(p+length(startToken):end),sprintf('\n\n        function '));
assert(~isempty(q),'[AF7R58ZZQ] next function boundary missing.');
e=p+length(startToken)+q(1)-1;
F=S(p:e);
end

function n=count_exact(s,pat)
n=numel(strfind(s,pat));
end

function s=read_utf8_binary(path)
fid=fopen(path,'rb'); assert(fid>=0); c=onCleanup(@()fclose(fid));
b=fread(fid,'*uint8');
s=native2unicode(b.','UTF-8');
end

function write_utf8_binary(path,s)
b=unicode2native(s,'UTF-8');
fid=fopen(path,'wb'); assert(fid>=0); c=onCleanup(@()fclose(fid));
fwrite(fid,uint8(b),'uint8');
end

function h=file_hash(path)
md=java.security.MessageDigest.getInstance('SHA-256');
fid=fopen(path,'rb'); assert(fid>=0); c=onCleanup(@()fclose(fid));
while true
    b=fread(fid,1024*1024,'*uint8');
    if isempty(b), break; end
    md.update(b);
end
u=typecast(md.digest(),'uint8');
h=lower(reshape(dec2hex(u,2).',1,[]));
end

function say(fid,varargin)
fprintf(fid,[varargin{1} '\n'],varargin{2:end});
fprintf([varargin{1} '\n'],varargin{2:end});
end

function safe_rmpath(p)
try, rmpath(p); catch, end
end

function safe_fclose(fid)
try, fclose(fid); catch, end
end
